INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98856, 'spa', 'Examinar o sondear a una persona, especialmente su vida interior — corazón, moti', 'Examinar o sondear a una persona, especialmente su vida interior — corazón, motivos, carácter. El Salmo 139:1 declara ''Me has escudriñado y conocido'', y el versículo 23 invita ese examen: ''Escudríñame, oh Dios''. Job 13:9 desafía a sus amigos: ''¿Os irá bien cuando él os escudriñe?'' Proverbios 18:17 señala que el vecino viene y ''escudriña'' al que primero expone su caso. El verbo aquí implica escrutinio penetrante del interior de la persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98858, 'spa', 'Un uso Qal resumido en Eclesiastés 12', 'Un uso Qal resumido en Eclesiastés 12:9 donde el Predicador ''escudriñó'' y ordenó muchos proverbios — la labor intelectual de compilar literatura sapiencial. Este sentido sirve de puente entre la exploración física del sentido 1 y el sondeo personal del sentido 2: aquí el objeto de investigación es el lenguaje y el significado mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98860, 'spa', 'El pasivo Nifal', 'El pasivo Nifal: ser investigable, sondeable o capaz de ser explorado plenamente — frecuentemente usado en negación. Jeremías 31:37 dice que los cimientos de la tierra no pueden ser ''escudriñados'' abajo, en paralelo con la imposibilidad de que Dios rechace a Israel. Jeremías 46:23 describe un bosque tan denso que ''no puede ser explorado''. La fuerza retórica depende del significado activo del verbo: si el escudriñar es exhaustivo, lo que no puede ser escudriñado es verdaderamente inescrutable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98876, 'spa', 'Escudriñamiento / investigación', 'El acto o resultado de un examen profundo, investigación o indagación en lo oculto o inescrutable. Se usa para las obras divinas que superan la comprensión humana (Job 5:9; 9:10; 11:7; Sal 145:3), para la deliberación interna y el autoexamen (''búsquedas del corazón'', Jue 5:15-16) y para las profundidades insondables de la autoridad real o el carácter humano (Pr 25:3). Aparece frecuentemente en la construcción negativa ''sin escudriñamiento''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98884, 'spa', 'Nobles, principales', 'Miembros de la clase gobernante hereditaria, nobles o patricios con rango social y autoridad política. Concentrado en Nehemías (2:16; 4:8, 14, 19; 5:7; 6:17; 7:5; 13:17), donde aparecen emparejados con los סְגָנִים (''oficiales'') como colíderes de la comunidad postexílica. También atestiguado en el período monárquico para las élites de la ciudad de Nabot (1 R 21:8, 11) y la nobleza judía exiliada por Nabucodonosor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98893, 'spa', 'Estar seco (resultativo)', 'Estar seco (resultativo): el Pual (pasivo intensivo), que expresa el estado resultante de algo ya completamente seco. Las cuerdas frescas de Sansón ''se habían secado'' y se volvieron quebradizas (Jue 16:7-8), perdiendo su poder de sujeción. Solo dos ocurrencias, ambas en la narrativa de Sansón, dan a este sentido un carácter narrativo distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98894, 'spa', 'Secarse, quedar árido', 'Secarse, quedar árido: el Qal intransitivo, que describe aguas, tierras o ríos que pierden su humedad. La tierra se seca después del diluvio (Gn 8:13), el Nilo se seca bajo juicio (Is 19:5-6), y Job observa que ''las aguas se retiran del mar y el río se agota y se seca'' (Job 14:11). El salmista recuerda cómo Dios secó el Mar Rojo (Sal 106:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98895, 'spa', 'Hacer secar, desecar', 'Hacer secar, desecar: el Hifil causativo, donde Dios o un agente poderoso remueve activamente la humedad. Dios declara ''yo seco el mar con mi reprensión'' (Is 50:2), Senaquerib se jacta de haber secado ríos (2 R 19:24; Is 37:25), y Dios promete secar las aguas de Babilonia (Jer 51:36; Is 51:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98907, 'spa', 'La condición intransitiva o estativa de estar desolado, arruinado o en estado de', 'La condición intransitiva o estativa de estar desolado, arruinado o en estado de abandono. Ciudades, santuarios y naciones enteras se describen en este estado. Amós 7:9 lo empareja con nashammu (''quedar asolado''), y Ezequiel 12:20 lo pone en paralelo con shamem (''estar desolado''). Nehemías 2:3 y 2:17 lo aplican a las murallas destruidas de Jerusalén. El español ''desolada'' y el francés ''ruines'' captan sistemáticamente este sentido de espacio vaciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98911, 'spa', 'El causativo Hifil que significa asolar activamente, destruir o llevar a la ruin', 'El causativo Hifil que significa asolar activamente, destruir o llevar a la ruina. Aquí el sujeto es el devastador: Senaquerib en 2 Reyes 19:17, o Dios mismo en Isaías 42:15. Sofonías 3:6 declara que naciones enteras han sido asoladas. El alemán ''verwüsten'' y el español ''asolaron'' reflejan la devastación activa que esta forma transmite, distinguiéndola del pasivo ''yacer en ruinas'' del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98914, 'spa', 'El participio Hifil sustantivado que funciona como nombre de agente', 'El participio Hifil sustantivado que funciona como nombre de agente: ''destructor'' o ''el que asola''. En Jueces 16:24 los filisteos llaman a Sansón ''el destructor de nuestra tierra'', e Isaías 49:17 promete que los destructores de Sion se apartarán de ella. Este uso nominal cristaliza la acción del verbo en un título personal de devastación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98925, 'spa', 'Atacar o guerrear', 'Atacar o hacer la guerra, empleado para asaltos militares y combate mutuo. En Jeremías 50:21, el imperativo Qal חֲרֹב ordena el ataque contra los territorios de Babilonia, emparejado con ''destruir por completo (הַחֲרֵם) tras ellos''. Jeremías 50:27 extiende el sentido a la matanza de los guerreros babilónicos. En 2 Reyes 3:23, el Nifal/Hofal describe a los reyes moabitas atacándose unos a otros (נֶחֶרְבוּ הַמְּלָכִים).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98927, 'spa', 'espada, arma de guerra', 'Arma con filo usada en combate, ejecución y juicio divino, abarcando virtualmente todas las ocurrencias. Incluye las espadas literales empuñadas por soldados y reyes (Gn 34:26; Éx 17:13), la espada flamígera que guarda el Edén (Gn 3:24) y la personificada «espada de YHWH» como instrumento de maldición pactual e ira profética (Lv 26:25; Jer 14:12). Las glosas convergen notablemente: espada, sword, épée, Schwert.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98950, 'spa', 'cuchillos de pedernal', 'Cuchillos de pedernal, como en Josué 5:2-3, donde Dios ordena a Josué fabricar «cuchillos de pedernal» para la circuncisión. Las glosas multilingües cambian decisivamente aquí: inglés knives-of, español cuchillos-de y francés couteaux-de indican un instrumento cortante distinto de la espada bélica. La forma constructa plural חַרְבוֹת צֻרִים los marca como implementos rituales, no armas de campo de batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98954, 'spa', 'ruinas (anomalía textual)', 'Probable anomalía textual-semántica en 2 Cr 34:6, donde las glosas leen «en sus ruinas» (inglés in-their-ruins, español en-sus-ruinas), sugiriendo que el texto subyacente refleja el homófono חָרְבוֹת (ruinas, de חָרַב «estar desolado») en vez del sentido de arma. Las tradiciones traductoras divergen en este pasaje problemático: francés y alemán retienen épée/Schwert.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98971, 'spa', 'Arruinado, desolado', 'En estado de ruina, devastación o desolación, usado para ciudades, edificios y lugares habitados que han sido destruidos o abandonados. Los textos proféticos emplean este adjetivo para crear contrastes poderosos: la desolación de Jeremías ''sin hombre ni bestia'' (Jer 33:10, 12), la visión de Ezequiel de ciudades arruinadas reconstruidas, y la reprensión de Hageo al pueblo que descuida el templo en ruinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98975, 'spa', 'Sequía, aridez, calor', 'Aridez extrema, sequía o calor abrasador que marchita la vegetación y amenaza la supervivencia. Jacob la cita entre las penalidades del trabajo pastoral (Gn 31:40), Gedeón la utiliza como la condición opuesta al rocío sobre el vellón (Jue 6:37, 39) y Job la contrasta con el deshielo para describir los ciclos de la naturaleza (Job 24:19). Los profetas la invocan como instrumento de juicio divino: sequía convocada sobre Babilonia y vinculada a la infidelidad del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98982, 'spa', 'Desolación y ruina', 'Estado de devastación total aplicado a ciudades y regiones bajo juicio divino. En Isaías 61:4, la misión del Siervo incluye reconstruir ''ciudades de חֹרֶב'' (en paralelo con שְׁמָמוֹת y חָרְבוֹת, ''asolamientos y ruinas''). Jeremías 49:13 lo emplea respecto al destino venidero de Bosra, y Ezequiel 29:10 lo compone como ''חָרְבוֹת חֹרֶב'' (''ruinas de desolación'') sobre Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98983, 'spa', 'Horeb (Monte Horeb)', 'Horeb (Monte Horeb): nombre propio del monte sagrado en el desierto del Sinaí donde Dios se apareció a Moisés y entregó el pacto a Israel. Identificado como ''el monte de Dios'' en Éxodo 3:1 (la zarza ardiente) y 1 Reyes 19:8 (la huida de Elías), y usado como la designación preferida para el Sinaí a lo largo de Deuteronomio (Deut 1:2, 6, 19; 4:10, 15; 5:2; 9:8, 12, 16; 18:16; 28:69). La etimología proviene de חָרַב (''estar seco''), evocando el paisaje árido del desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98989, 'spa', 'estado de ruina o desolación', 'estado de ruina o desolación');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98990, 'spa', 'ruinas de un lugar', 'ruinas de un lugar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98997, 'spa', 'desierto, páramo', 'desierto, páramo');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99019, 'spa', 'Tierra seca', 'Tierra seca o suelo firme, la superficie sólida que queda expuesta cuando el agua retrocede o es dividida sobrenaturalmente. Casi todas las apariciones implican un contexto milagroso: la apertura del mar de los Juncos (Éx 14:21), el cruce del Jordán en seco (Jos 3:17; 4:18) y el paso de Elías y Eliseo por el Jordán (2 R 2:8). La evidencia multilingüe es unánime: español ''tierra seca'', francés ''terre ferme''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99027, 'spa', 'temblar, estremecerse de temor', 'temblar, estremecerse de temor');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99028, 'spa', 'aterrorizar, hacer temblar', 'aterrorizar, hacer temblar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99042, 'spa', 'inquietarse, mostrar solicitud', 'inquietarse, mostrar solicitud');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99049, 'spa', 'Tembloroso, temeroso', 'Adjetivo verbal que abarca el temblor físico por miedo y el temblor reverente ante Dios. En Jue 7:3 aparece en paralelo con ''temeroso'' (יָרֵא) como motivo de exención militar. En 1 Sam 4:13 Elí tiembla por el arca. En Esdras e Isaías designa al remanente fiel que tiembla ante la palabra divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99055, 'spa', 'Temblor, miedo, angustia', 'Temblor, miedo o pavor angustioso: un estado en el que el cuerpo se estremece por terror, pánico divino o profunda aprensión. Abarca desde el violento estremecimiento físico de Isaac al descubrir el engaño (Gn 27:33), pasando por el ''temblor de Dios'' que golpeó a todo un campamento militar (1 S 14:15), hasta la ''inquietud interior'' que Eliseo percibió en la sunamita (2 R 4:13). Ezequiel 26:16 lo emplea para describir el horror de los príncipes del mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99065, 'spa', 'se encendió la ira', 'se encendió la ira');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99073, 'spa', 'impacientarse, irritarse', 'impacientarse, irritarse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99083, 'spa', 'los que se enfurecen (Nifal)', 'los que se enfurecen (Nifal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99089, 'spa', 'ardientemente, con fervor', 'ardientemente, con fervor');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99096, 'spa', 'encender (la ira divina contra alguien)', 'encender (la ira divina contra alguien)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99107, 'spa', 'Maleza y desolación', 'Maleza o plantas silvestres que indican abandono y desolación. Job 30:7 describe a marginados refugiándose «entre las ortigas». Proverbios 24:31 advierte que el campo del perezoso se cubre de cardos. Sofonías 2:9 profetiza que Moab será «posesión de ortigas», un yermo. La incertidumbre botánica se refleja en las diversas traducciones según cada lengua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99109, 'spa', 'ardor encendido de ira', 'ardor encendido de ira');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99116, 'spa', 'furor, ira encendida', 'furor, ira encendida');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99133, 'spa', 'Diligente', 'Describe a la persona de mente aguda y laboriosa: el diligente. Usado como sustantivo en Proverbios para contrastar con el perezoso (עָצֵל) y el de manos flojas (רְמִיָּה). El español ''diligente'' capta esta extensión figurada desde la agudeza física a la laboriosidad moral (Pr 10:4; 12:24; 13:4; 21:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99135, 'spa', 'Agudo, afilado', 'Adjetivo que significa agudo o puntiagudo, usado como atributo de un trillo: ''un trillo nuevo y afilado con dientes'' (Is 41:15). En Job 41:30 describe el vientre del cocodrilo como tiestos agudos. Las glosas multilingües se dividen entre el instrumento (''trillo'' en español) y su cualidad (''agudo''), revelando el estrecho vínculo entre herramienta y atributo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99136, 'spa', 'Trillo', 'El trillo propiamente dicho (חָרוּץ/מוֹרַג), una pesada plataforma agrícola con bordes cortantes usada para separar el grano de la paja. Isaías 28:27 lo menciona junto a la rueda del carro como equipo estándar de trilla. En Amós 1:3 se convierte en arma de atrocidad —Damasco ''trilló a Galaad con trillos de hierro''— y el español ''con trillos de hierro'' conserva esta imagen vívida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99141, 'spa', 'Oro, oro fino', 'Oro precioso refinado, sinónimo poético de זָהָב usado exclusivamente en contextos literarios elevados. Siempre en paralelo con plata (כֶּסֶף), sirve como estándar del mayor valor terrenal que la sabiduría sobrepasa (Prov 3:14; 8:10, 19; 16:16). En los Salmos evoca el esplendor visual del metal reluciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99150, 'spa', 'Mago, sacerdote-adivino', 'Mago o sacerdote-lector de la corte egipcia, versado en textos sagrados y magia ritual. Los chartummim del faraón intentan interpretar sueños (Gn 41:8, 24) y duplicar las señales de Moisés y Aarón mediante sus artes secretas (Éx 7:11, 22; 8:3, 14-15). Su fracaso progresivo — replicando la sangre y las ranas pero no los mosquitos — dramatiza la superioridad del poder de Dios. Son heridos con úlceras junto con los demás egipcios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99157, 'spa', 'mago cortesano', 'Mago, sacerdote-adivino vinculado a una corte real. En Daniel, חַרְטֹם designa a practicantes profesionales de las artes ocultistas convocados para interpretar suenos y senales junto a encantadores y hechiceros (Dn 2:10, 27; 4:7, 9; 5:11). Fracasan sistematicamente ante los misterios divinos, sirviendo como contraste literario frente a la sabiduria otorgada por Dios a Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99158, 'spa', 'Ardor de ira', 'Calor abrasador de la ira, exclusivamente en la frase constructa חֳרִי אַף (''ardor de la ira''). Intensifica אַף (''ira, nariz'') añadiendo la imagen de fuego. Describe la furia de Moisés ante el Faraón (Éx 11:8), la indignación de Jonatán (1 Sam 20:34), la ira divina (Dt 29:24) y el furor de ejércitos y reyes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99165, 'spa', 'Horeo (gentilicio)', 'Los horeos, grupo étnico pre-edomita que habitaba la región montañosa de Seir, siempre con artículo (הַחֹרִי). El nombre probablemente significa ''morador de cuevas'' (de חֹר, ''cueva''), apropiado para la geografía de Edom. Génesis 36:20 identifica a ''Seir el horeo'' como ancestro. Deuteronomio 2:12, 22 presenta su desplazamiento por Esaú como ejemplo de la soberanía divina sobre los territorios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99168, 'spa', 'Pueblo troglodita de Seir', 'Gentilicio de los habitantes predomitas del monte Seir, entendidos como ''moradores de cuevas'' (de חֹר, ''cueva''). Génesis 36:20-30 ofrece el relato más detallado, listando a Seir el horeo y sus descendientes como los clanes originales de la región. En 1 Crónicas 1:39, Horí aparece como hijo de Lotán, jefe horeo. El nombre también surge como nombre propio en Números 13:5 para el padre de Safat.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99172, 'spa', 'Cortes e instrumentos', 'Cortes de queso o instrumentos cortantes de hierro. 1 Samuel 17:18 lo usa concretamente para «diez cortes de leche», rebanadas de queso que David llevó a sus hermanos. 2 Samuel 12:31 y 1 Crónicas 20:3 lo emplean para instrumentos de trabajo forzado o tortura: David sometió a los amonitas «con sierras y trillos de hierro». La amplitud semántica refleja el concepto subyacente de cortar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99173, 'spa', 'Arada y labranza', 'Arada o temporada de labranza. Génesis 45:6 advierte sobre la hambruna: «no habrá ni arada ni cosecha». Éxodo 34:21 ordena descansar en sábado «en la arada y en la siega», reconociendo que incluso estas temporadas exigentes requieren reposo. 1 Samuel 8:12 describe el servicio obligatorio: «para arar su arada», un acusativo cognado que enfatiza la labor impuesta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99178, 'spa', 'destruir totalmente (Hifil activo)', 'destruir totalmente (Hifil activo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99187, 'spa', 'destruir, devastar (uso aislado en Isaías)', 'destruir, devastar (uso aislado en Isaías)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99188, 'spa', 'anatematizar, hacer caer bajo el anatema', 'anatematizar, hacer caer bajo el anatema');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99194, 'spa', 'consagrar o dedicar a Dios', 'consagrar o dedicar a Dios');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99214, 'spa', 'ser destruido (Hofal pasivo, idolatría)', 'ser destruido (Hofal pasivo, idolatría)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99215, 'spa', 'ser consagrado irrevocablemente (Hofal pasivo)', 'ser consagrado irrevocablemente (Hofal pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99216, 'spa', 'ser confiscado (Hofal, uso postexílico)', 'ser confiscado (Hofal, uso postexílico)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99218, 'spa', 'Anatema, consagración a la destrucción — persona, ciudad u objeto irrevocablemen', 'Anatema, consagración a la destrucción — persona, ciudad u objeto irrevocablemente dedicado a Dios mediante su destrucción total, sin posibilidad de retención ni redención humana. Es el sentido dominante, que rige los relatos de conquista: Jericó (Jos 6:17-18), la transgresión de Acán (Jos 7:1-15) y el anatema contra Amalec que Saúl no ejecutó (1 Sam 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99220, 'spa', 'Cosa consagrada, ofrenda sagrada — bien dedicado irrevocablemente a Dios como of', 'Cosa consagrada, ofrenda sagrada — bien dedicado irrevocablemente a Dios como ofrenda sagrada permanente, no destruido sino apartado para uso sacerdotal o del templo. Levítico 27:21, 28 establece que un campo o posesión bajo חֵרֶם se convierte en santo para el SEÑOR y pasa a los sacerdotes; Números 18:14 asigna todo חֵרֶם en Israel a la línea de Aarón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99226, 'spa', 'Mi anatema, decreto divino de maldición — el decreto personal de Dios de anatema', 'Mi anatema, decreto divino de maldición — el decreto personal de Dios de anatema o maldición, expresado en primera persona posesiva. En 1 Reyes 20:42 se reprende a Acab por liberar al ''hombre de mi anatema'' (חֶרְמִי), y en Isaías 34:5 Dios declara que su espada desciende sobre el pueblo de ''mi maldición'' (חֶרְמִי). El sufijo posesivo marca esto como prerrogativa divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99235, 'spa', 'Red, red barredera', 'Red o red barredera usada para pescar o atrapar presas. Etimológicamente vinculada al concepto de material perforado (cf. árabe mukharram), aparece tanto en contextos literales como figurados. La red del cazador atrapa en Miqueas 7:2 y Eclesiastés 7:26, mientras que la red barredera del pescador domina en Ezequiel (26:5, 14; 32:3; 47:10) y Habacuc (1:15-17), donde el imperio caldeo se personifica como pescador de naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99244, 'spa', 'Harim (nombre propio)', 'La familia sacerdotal de Harim, asignada a la tercera división en la organización del servicio del templo por David (1 Cr 24:8). Sus descendientes regresaron del exilio (Esd 2:39; Neh 7:42) y figuran en el registro sacerdotal de la generación de Joiaquim (Neh 12:15). Algunos miembros fueron hallados culpables de matrimonios con mujeres extranjeras (Esd 10:21). Un representante selló el pacto de Nehemías (Neh 10:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99246, 'spa', 'Horma (topónimo)', 'El nombre propio Horma designa una ciudad real cananea en el Neguev, originalmente llamada Sefat (Jue 1:17), renombrada después de que Israel consagró a sus habitantes al exterminio (חֵרֶם). El nombre mismo es un monumento etimológico a la guerra santa. Aparece en la narración del ataque prematuro de Israel (Nm 14:45), la campaña exitosa bajo Moisés (Nm 21:3) y las asignaciones tribales a Simeón (Jos 15:30; 19:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99251, 'spa', 'Hermón (topónimo)', 'El nombre propio Hermón (חֶרְמוֹן), que designa la montaña más alta de la cordillera del Antilíbano en el extremo norte de Israel. Las trece ocurrencias marcan este pico como referencia fronteriza en descripciones territoriales (Dt 3:8; Jos 11:17; 12:1; 13:5, 11). La raíz חרם (''consagrado, dedicado'') probablemente refleja la antigua significación cultual de la montaña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99258, 'spa', 'Harán (topónimo mesopotámico)', 'Ciudad antigua de la Alta Mesopotamia (actual Harrán, Turquía), ubicada en una importante ruta comercial entre Nínive y el Mediterráneo. Taré se asentó allí tras dejar Ur y murió en ese lugar (Gn 11:31-32). Abraham partió de Harán a los 75 años rumbo a Canaán (Gn 12:4-5), y Jacob huyó allí para escapar de Esaú y buscar esposa entre la familia de Labán (Gn 27:43; 28:10; 29:4). Ezequiel 27:23 la menciona como centro de comercio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99264, 'spa', 'Gentilicio de Sanbalat', 'Designación étnica o geográfica de Sanbalat como «el horonita», oriundo de Bet-horón o sus cercanías. Nehemías 2:10, 19 lo presentan como opositor: «cuando Sanbalat el horonita oyó» los planes de restauración. Nehemías 13:28 relata su alianza matrimonial con la familia del sumo sacerdote. El artículo («el horonita») sugiere un gentilicio bien conocido que lo distinguía de otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99265, 'spa', 'Ciudad moabita profética', 'Ciudad moabita que aparece exclusivamente en oráculos proféticos contra Moab. Isaías 15:5 la sitúa en una ruta de huida (''por el camino de Horonaim levantan grito de destrucción''), mientras Jeremías 48:3 repite el clamor, 48:5 nombra ''la bajada de Horonaim'' como lugar de llanto, y 48:34 la incluye en el barrido geográfico de la devastación de Moab. La terminación dual (-ayim) sugiere un asentamiento doble.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99267, 'spa', 'Sol o topónimo', 'El sol o un topónimo Heres. Job 9:7 habla de Dios que «ordena al sol y no sale». Jueces 8:13 menciona «la subida de Heres» (o «antes del sol»), referencia geográfica. Jueces 14:18 presenta un enigma textual: «antes de que el sol se pusiera» (o «antes de entrar en la cámara»). La superposición de significados celestes y geográficos genera desafíos interpretativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99271, 'spa', 'afrentar, insultar, vituperar', 'afrentar, insultar, vituperar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99273, 'spa', 'desafiar con desprecio', 'desafiar con desprecio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99286, 'spa', 'despreciar la propia vida', 'despreciar la propia vida');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99295, 'spa', 'reprender, avergonzar', 'reprender, avergonzar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99301, 'spa', 'Invierno, estación fría', 'El invierno o la estación fría y lluviosa del año. Emparejado con קַיִץ (''verano'') en la promesa estacional fundacional de Génesis 8:22 y Salmo 74:17, ancla el ciclo anual. Jeremías 36:22 lo sitúa en el noveno mes (noviembre-diciembre), cuando Joacim se sienta junto a un brasero. La ''casa de invierno'' de Amós 3:15 y las aguas perennes de Zacarías 14:8 confirman la referencia estacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99305, 'spa', 'Otoño, plenitud vital', 'Otoño o tiempo de cosecha, con una extensión figurada a la plenitud o vigor de la vida. En Job 29:4, חָרְפִּי (''mi otoño'') evoca la estación de madurez y abundancia como metáfora de la prosperidad pasada de Job, cuando el consejo de Dios reposaba sobre su tienda. El cognado árabe kharif (''fruto recién cosechado, otoño'') apoya el matiz de temporada de cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99308, 'spa', 'deshonra, vergüenza, afrenta', 'deshonra, vergüenza, afrenta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99329, 'spa', 'insultos, reproches verbales', 'insultos, reproches verbales');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99346, 'spa', 'defecto vergonzoso, tacha', 'defecto vergonzoso, tacha');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99354, 'spa', 'Determinar, decretar', 'Determinar, decretar o decidir con autoridad, frecuentemente sobre veredictos divinos irrevocables. El participio pasivo חָרוּץ en Isaías 10:22 señala una determinación firme e inalterable. Job 14:5 habla de días ''determinados'' para el ser humano; Isaías 28:22 advierte sobre una destrucción ''decretada'' sobre toda la tierra. Es la acepción más frecuente, presente tanto en formas activas como participiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99356, 'spa', 'Afilar, cortar', 'Cortar, afilar o mutilar físicamente. Levítico 22:22 enumera al animal ''mutilado'' junto a los ciegos y los lisiados, confirmando el sentido corporal concreto. La expresión idiomática de Éxodo 11:7 y Josué 10:21, donde ningún perro ''afila su lengua'', representa el habla hostil como una espada contenida. La imagen física subyace a la extensión metafórica hacia el juicio decisivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99362, 'spa', 'Actuar con decisión', 'Actuar con decisión o diligencia urgente, una extensión poco frecuente de los sentidos de cortar y decidir. En 2 Samuel 5:24, se ordena a David que ''actúe con decisión'' al oír el sonido en los árboles de bálsamo. Este sentido tiende un puente entre la agudeza física y la resolución mental: cortar la vacilación y moverse con energía determinada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99368, 'spa', 'rechinar los dientes', 'Rechinar o crujir los dientes como expresion de ira intensa, hostilidad o intencion maliciosa dirigida contra otra persona. Las cinco apariciones son poeticas, tipicamente con ''dientes'' (שִׁנַּיִם/שֵׁן) como instrumento. El gesto hostil aparece en lamento (Job 16:9), imprecacion (Sal 35:16), instruccion sapiencial (Sal 37:12; 112:10) y elegía comunitaria (Lam 2:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99369, 'spa', 'Ser quemado o carbonizado', 'El sentido pasivo Nifal de ser carbonizado, chamuscado o quemado por el fuego. Se usa de la madera en la alegoría de la vid de Ezequiel: la vid se ''carboniza'' en ambos extremos y su centro ''se quema'' (Ez 15:4-5). También se aplica a los fuelles consumidos en el fuego refinador de Jeremías 6:29 y a los huesos ''carbonizados'' en Ezequiel 24:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99371, 'spa', 'Arder o resplandecer', 'El sentido intransitivo Qal de arder, resplandecer o consumirse por el calor. En Job 30:30, la piel de Job se ennegrece y sus huesos ''arden de fiebre''. Isaías 24:6 advierte que los moradores de la tierra ''arden'' bajo una maldición. Ezequiel 24:11 ordena que el caldero vacío ''arda'' sobre las brasas. El sentido apunta a un proceso activo y continuo de combustión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99373, 'spa', 'Arder de ira', 'Una extensión metafórica Nifal al ámbito emocional: arder de ira, estar enfurecido. En Cantares 1:6, la sulamita recuerda que los hijos de su madre ''se encendieron contra ella'' (נִחֲרוּ בִי), comparando su enojo con el fuego. La metáfora térmica se conserva en el hebreo: la ira como combustión interna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99376, 'spa', 'Encender o avivar', 'El sentido intensivo Pilpel de encender o avivar el fuego, aplicado al individuo pendenciero que enciende la discordia. En Proverbios 26:21, ''como el carbón a las brasas y la leña al fuego, así es el hombre conflictivo para encender (לְחַרְחֵר) contiendas''. La raíz reduplicada intensifica el significado base: no solo arder, sino provocar el fuego activa y persistentemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99377, 'spa', 'Resecarse, quedar ronco', 'Un sentido Nifal de desecación: quedar reseco, deshidratado o ronco por el calor y el esfuerzo. En el Salmo 69:3, el salmista clama: ''Mi garganta está reseca'' (נִחַר גְּרוֹנִי) de tanto invocar a Dios. Aquí el ardor no es de llama sino de deshidratación: las cuerdas vocales secas y desgastadas por el clamor sostenido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99381, 'spa', 'Cerámica, barro (material)', 'Cerámica, barro (material): alfarería o arcilla cocida como sustancia material, típicamente en la expresión constructa ''vasija de barro'' (כְּלִי חֶרֶשׂ). Predomina en las regulaciones de pureza levíticas donde tales vasijas, por ser porosas y sin esmaltar, debían romperse si se contaminaban (Lev 6:28, 11:33, 15:12). También aparece en Jer 32:14 como tinaja de almacenamiento y en Prov 26:23 como esmalte de plata sobre barro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99383, 'spa', 'Tiesto, fragmento (pedazo roto)', 'Tiesto, fragmento (pedazo roto): un fragmento o tiesto roto de una vasija de barro destrozada. Job raspa sus llagas con uno (Job 2:8), e Isaías emplea la imagen con fuerza: un trozo ''demasiado pequeño para llevar una brasa'' (Isa 30:14) y ''un tiesto entre los tiestos de la tierra'' que desafía a su Hacedor (Isa 45:9). Ezequiel profetiza vívidamente que Jerusalén roerá los tiestos de su propia copa de juicio (Ezeq 23:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99390, 'spa', 'Maquinar el mal (Qal) — tramar, planear, especialmente el mal', 'Maquinar el mal (Qal) — tramar, planear, especialmente el mal. Seis ocurrencias, cinco concentradas en Proverbios, donde el verbo transfiere metafóricamente la acción de arar a la maquinación mental. ''No maquines mal contra tu prójimo'' (Prov 3:29); ''corazón que trama planes perversos'' (Prov 6:18); ''los que traman mal'' frente a ''los que traman bien'' (Prov 12:20; 14:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99392, 'spa', 'Arar (Qal) — el sentido activo dominante del Qal con 15 ocurrencias, que abarca ', 'Arar (Qal) — el sentido activo dominante del Qal con 15 ocurrencias, que abarca la labranza literal del suelo con bueyes y arado. Deuteronomio 22:10 prohíbe arar con buey y asno juntos; 1 Reyes 19:19 presenta a Eliseo arando con doce yuntas; Job 1:14 describe la escena pastoral de los bueyes arando.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99393, 'spa', 'Ser arado (Nifal) — dos ocurrencias en el Nifal pasivo, ambas en el mismo orácul', 'Ser arado (Nifal) — dos ocurrencias en el Nifal pasivo, ambas en el mismo oráculo profético: Miqueas 3:12 y su cita en Jeremías 26:18, donde Jerusalén ''será arada como un campo''. Es una de las imágenes más devastadoras de la literatura profética: una ciudad reducida a tierra de labranza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99394, 'spa', 'Maquinar en silencio (Hifil) — una única ocurrencia en 1 Samuel 23', 'Maquinar en silencio (Hifil) — una única ocurrencia en 1 Samuel 23:9, donde David percibió que Saúl estaba ''tramando'' mal contra él. La forma causativa del Hifil intensifica el aspecto de conspiración, añadiendo una dimensión de maquinación deliberada y calculada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99405, 'spa', 'Grabado (Qal pasivo) — participio pasivo del Qal en Jeremías 17', 'Grabado (Qal pasivo) — participio pasivo del Qal en Jeremías 17:1, donde el pecado de Judá se describe como ''grabado con punzón de hierro, inscrito con punta de diamante en la tabla de su corazón''. Conecta a חָרַשׁ con su cognado en otras lenguas semíticas: el arameo חֲרַט (''grabar'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99410, 'spa', 'callar, guardar silencio', 'callar, guardar silencio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99427, 'spa', 'hacer callar, reducir al silencio', 'hacer callar, reducir al silencio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99441, 'spa', 'estar sordo, no oír', 'estar sordo, no oír');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99446, 'spa', 'Bosque, altura arbolada', 'Un bosque, espesura o altura arbolada: una extensión de densa cobertura arbórea típicamente en terreno elevado. El uso narrativo en 1 Samuel 23:15-19 lo empareja con ''monte'' y ''fortaleza'', indicando tierras altas boscosas aptas para esconderse. En 2 Crónicas 27:4 designa zonas de bosque donde Jotam erigió fortificaciones. El acadio hurshu confirma el sentido de tierras altas arboladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99453, 'spa', 'Sordo, incapaz de oír', 'Sordo, incapaz de oír, ya sea como condición física literal o como imperceptibilidad espiritual figurada. Éxodo 4:11 coloca la sordera junto a la mudez como condiciones bajo la autoridad soberana de Dios. Levítico 19:14 prohíbe maldecir al sordo, subrayando su vulnerabilidad. Los profetas transforman el adjetivo en metáfora de la obstinación espiritual voluntaria (Is 42:18-19; 43:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99459, 'spa', 'artesano, artífice (general)', 'artesano, artífice (general)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99462, 'spa', 'grabador, escultor', 'grabador, escultor');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99468, 'spa', 'herrero, metalúrgico', 'herrero, metalúrgico');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99469, 'spa', 'carpintero, ebanista', 'carpintero, ebanista');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99480, 'spa', 'Tallado artesanal', 'Tallado o grabado hábil de materiales duros (madera, piedra) como oficio especializado. Las cuatro apariciones se encuentran en las instrucciones del Tabernáculo en Éxodo (31:5; 35:33), emparejadas con materiales específicos mediante la cadena constructa. El término denota una destreza otorgada divinamente para dar forma artística a los materiales del santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99481, 'spa', 'Ciudad de Sísara', 'Haroset-ha-goyim (Haroset de las naciones), la ciudad de Sísara. Jueces 4:2 sitúa a Sísara «en Haroset de las naciones». Jueces 4:13 describe cómo convoca sus fuerzas «desde Haroset» para la batalla. Jueces 4:16 relata la persecución de Barac hasta «Haroset». El marco geográfico gira en torno a esta fortaleza militar del valle septentrional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99484, 'spa', 'diseñar, oficio artístico', 'Idear diseños artísticos: el sentido artesanal con 15 ocurrencias, concentradas en Éxodo. El participio Qal חֹשֵׁב describe al maestro artesano que idea patrones en oro, plata y tela de colores para el tabernáculo (Éx 26:1, 31; 28:6, 15). Esta notable extensión muestra cómo «pensar» abarca el diseño creativo: el trabajo de la mente hecho visible en textiles y metalistería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99486, 'spa', 'planear, idear, tramar', 'Planear, idear o tramar: el sentido más frecuente con 41 ocurrencias. Suele llevar connotación negativa: Est 9:24 dice que Amán «maquinó» destruir a los judíos; Mi 2:1 denuncia a quienes «traman maldad». El árabe dabbara (دَبَّرَ) y el coreano kkoehada (꾀하다) capturan esta intriga deliberada. La conjugación Piel a menudo intensifica el matiz hacia la maquinación persistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99487, 'spa', 'calcular, contar', 'Calcular, contar o computar numéricamente: el sentido aritmético con 8 ocurrencias, agrupadas en las leyes de redención de propiedades de Levítico (25:27, 50, 52; 27:18, 23). El árabe ḥasaba (حَسَبَ «calcular/contar»), el coreano gyesanhada (계산하다) y el suajili hesabu preservan este significado concreto de cómputo, que puede ser el núcleo etimológico del que brotaron los sentidos abstractos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99488, 'spa', 'ser contado, ser considerado', 'Nifal e Hitpael pasivo/reflexivo: «ser contado, ser considerado, ser tenido por». Treinta y una ocurrencias muestran personas o cosas asignadas a una categoría. Lv 25:31 dice que las aldeas sin muro «serán contadas» como campo abierto; Gn 31:15 presenta a Lea y Raquel preguntando si son «tenidas por» extranjeras. El árabe yuḥsabu (يُحْسَبُ) preserva fielmente la formación pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99491, 'spa', 'pensar, considerar, suponer', 'Pensar, reflexionar o suponer: actividad cognitiva general sin implicar necesariamente planificación (13 ocurrencias). Gn 38:15 dice que Judá «pensó» que Tamar era una prostituta; 1 S 1:13 que Elí «supuso» que Ana estaba borracha. El árabe ẓanna (ظَنَّ) y el coreano saenggakhada (생각하다) capturan este sentido neutro de formarse una impresión mental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99495, 'spa', 'proponerse, determinar', 'Proponerse o determinar: resolución deliberada sobre un curso de acción (5 ocurrencias). Gn 50:20 contiene su expresión más célebre: «Vosotros lo pensasteis (חָשַׁב) para mal, pero Dios lo pensó (חָשַׁב) para bien». Jer 49:20 y 50:45 lo aplican al propósito divino contra las naciones. Este sentido subraya la voluntad resuelta, enmarcando a חָשַׁב como el verbo del designio soberano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99502, 'spa', 'estimar, tener por', 'Estimar, valorar o considerar a alguien como poseedor de cierto estatus (11 ocurrencias). Gn 15:6 es paradigmático: Dios «contó» la fe de Abram por justicia. Job 19:11, 15 lamenta ser «tenido por» adversario y extraño. Este juicio evaluativo asigna valor o identidad a otro, yendo más allá del mero pensamiento hacia una valoración activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99580, 'spa', 'Cinto tejido del efod', 'Cinto hábilmente tejido o faja del efod, accesorio de la vestimenta sacerdotal. El sustantivo חֵשֶׁב aparece exclusivamente en textos sacerdotales (Éx 28:8, 27, 28; 29:5; 39:5, 20, 21; Lv 8:7), siempre en estado constructo con ''efod'', designando la faja decorativa que aseguraba el efod a la cintura. BDB lo describe como ''obra ingeniosa'', y la raíz חשׁב implica artesanía experta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99586, 'spa', 'Razonamiento o cálculo', 'Razonamiento, cálculo o investigación sistemática. Eclesiastés 7:25 describe la búsqueda de «sabiduría y cálculo», la indagación racional de la realidad. Eclesiastés 7:27 relata sumar «una cosa a otra para hallar la razón», cálculo metódico en busca de la verdad. Eclesiastés 9:10 señala que en el Seol «no hay cálculo», ya no hay actividad intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99587, 'spa', 'Hesbón (ciudad)', 'Hesbón (ciudad)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99598, 'spa', 'Hasabías (nombre propio)', 'Nombre propio masculino Hasabías (חֲשַׁבְיָה / חֲשַׁבְיָהוּ), compuesto teofórico que significa ''Yah(u) ha contado'', designa a múltiples levitas a lo largo de la historia de Israel: músicos del templo bajo David (1 Cr 25:3, 19), oficiales tribales y regionales (1 Cr 26:30; 27:17), levitas de la era de Josías (2 Cr 35:9), y numerosos funcionarios postexílicos bajo Esdras y Nehemías (Esd 8:19, 24; Neh 10:11; 11:15, 22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99604, 'spa', 'Guardar silencio deliberadamente (Hifil)', 'Guardar silencio deliberadamente (Hifil): silencio deliberado en el tronco Hifil, una decisión intencional de callarse. En Jueces 18:9 los espías danitas instan a sus hermanos a no quedarse callados sino a actuar; en 2 Reyes 7:9 los leprosos a la puerta de Samaria se dan cuenta de que están callando cuando deberían compartir las buenas noticias. Isaías 42:14 y Salmo 39:2 usan la primera persona: Dios y el salmista relatan cada uno su contención elegida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99605, 'spa', 'Estar en silencio (Qal)', 'Estar en silencio (Qal): el estado básico Qal de estar o permanecer en silencio, sin la intencionalidad intensificada del Hifil. Eclesiastés 3:7 lo empareja con hablar como un ritmo humano natural. En Isaías 62:1 y 62:6, el profeta jura no callar hasta que la justicia de Sion resplandezca, y a los centinelas sobre los muros de Jerusalén se les dice que nunca callen; aquí el Qal describe un estado predeterminado que debe romperse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99615, 'spa', 'Acallar a otros (Hifil causativo)', 'Acallar a otros (Hifil causativo): sentido causativo Hifil de hacer callar o acallar a otros, atestiguado una sola vez en Nehemías 8:11, donde los levitas calman al pueblo que llora para que puedan escuchar la lectura de la Ley. El contexto de una asamblea pública hace que este sentido sea distinto: el sujeto actúa sobre otros para producir silencio en lugar de practicarlo personalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99616, 'spa', 'Aquietarse, ser acallado', 'Aquietarse, ser acallado: el aquietamiento o acallamiento de fuerzas naturales, atestiguado una sola vez en Salmo 107:29 donde Dios calma la tormenta y las olas ''se aquietaron''. Este uso Qal extiende la palabra más allá del habla humana hacia el mundo natural, describiendo la obediencia cósmica al mandato de Dios en un lenguaje que anticipa a Jesús calmando el mar en los Evangelios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99617, 'spa', 'nombre propio masculino', 'Nombre propio masculino (''considerado'') que designa al menos dos o tres individuos distintos en el Juda postexilico. Uno es un levita prominente descendiente de Merari que ayudo a repoblar Jerusalen (1 Cr 9:14; Neh 11:15). Otros dos son constructores que repararon diferentes secciones del muro bajo Nehemias (Neh 3:11, 23). En espanol se transcribe ''Hasub'' o ''Jasub.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99623, 'spa', 'Refrenar, contener — retener, contener o mantener bajo control una acción o fuer', 'Refrenar, contener — retener, contener o mantener bajo control una acción o fuerza. Dios refrenó a Abimelec de pecar (Gn 20:6), Abigail contuvo a David del derramamiento de sangre (1 Sam 25:39) y Joab detuvo al ejército (2 Sam 18:16). Job decide no ''refrenar'' su boca (Job 7:11). El énfasis está en frenar algo que de otro modo procedería: un acto de control o autocontrol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99625, 'spa', 'Retener, no dar — retener bienes, recursos o generosidad, la negativa a dar lo q', 'Retener, no dar — retener bienes, recursos o generosidad, la negativa a dar lo que uno podría. Génesis 22:12 y 22:16 celebran a Abraham porque ''no retuvo'' a su único hijo. Proverbios 21:26 contrasta al justo que da con liberalidad con quien retiene. Job 30:10 lamenta que sus acusadores ''no retuvieron'' su saliva de su rostro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99626, 'spa', 'Perdonar, mostrar misericordia — perdonar a alguien reteniendo el castigo, la de', 'Perdonar, mostrar misericordia — perdonar a alguien reteniendo el castigo, la destrucción o la severidad, misericordia expresada como contención. Proverbios 13:24 dice que quien ''escatima'' la vara aborrece a su hijo. Salmo 78:50 dice que Dios ''no perdonó'' sus vidas de la pestilencia. Esdras 9:13 reconoce que Dios castigó ''menos de lo que merecían nuestras iniquidades''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99640, 'spa', 'Reservar, guardar — reservar o guardar algo para una ocasión futura', 'Reservar, guardar — reservar o guardar algo para una ocasión futura. En Job 38:23, Dios pregunta a Job si ha visto los depósitos de granizo ''que reservé para el tiempo de angustia''. Esta única ocurrencia extiende la idea de retención de forma temporal: lo que se retiene ahora se guarda intencionalmente para un despliegue posterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99646, 'spa', 'Oscurecerse (la luz falla)', 'Oscurecerse (la luz falla): sentido intransitivo básico Qal: del cielo, sol, luna, estrellas o día que se oscurece o pierde luz. Abarca tanto la oscuridad natural (Éx 10:15, la plaga de langostas que bloquea el sol) como el oscurecimiento cósmico escatológico (Isa 13:10, Ecl 12:2). Job 3:9 maldice el día de su nacimiento deseando que sus estrellas matutinas se oscurezcan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99647, 'spa', 'Causar oscuridad (Hifil)', 'Causar oscuridad (Hifil): sentido causativo Hifil: oscurecer, provocar o imponer oscuridad. Dios activamente oscurece la luz de Egipto (Sal 105:28) y convierte la luz del día en noche (Amós 5:8). En Jer 13:16, el profeta advierte dar gloria a Dios antes de que él cause oscuridad sobre los montes. Job 38:2 lo usa retóricamente: ''¿Quién es este que oscurece el consejo?'' El causativo añade agencia teológica ausente del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99651, 'spa', 'Nublarse (de los ojos)', 'Nublarse (de los ojos): uso Qal especializado para ojos que se nublan, atestiguado en Lam 5:17 donde los ojos se han oscurecido de tanto llorar por la desolación de Sion. El contexto deja claro que se trata de una pérdida de visión causada por el dolor, no de oscuridad ambiental. La metáfora une lo físico y lo emocional: la vista que falla se convierte en expresión corporal del sufrimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99654, 'spa', 'Oscurecerse (de la piel)', 'Oscurecerse (de la piel): extensión Qal poco frecuente que describe la piel o apariencia corporal que se ennegrece u oscurece, encontrada en Lam 4:8 donde los antes resplandecientes nazareos ahora son más oscuros que el hollín. Señala una transformación visible causada por el hambre y el sufrimiento. Este sentido extiende el rango semántico de la raíz desde la oscuridad cósmica y ambiental hacia el cuerpo humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99663, 'spa', 'oscuridad, tinieblas, ausencia de luz', 'oscuridad, tinieblas, ausencia de luz');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99679, 'spa', 'Tiniebla profunda', 'Oscuridad o tiniebla profunda, empleada principalmente en textos poéticos y proféticos con connotaciones que trascienden la mera penumbra física. Designa el pavor sobrenatural en la visión del pacto de Abraham (Gn 15:12, ''una gran tiniebla''), la ceguera moral de los jueces injustos (Sal 82:5), la equivalencia de oscuridad y luz ante Dios (Sal 139:12) y la angustia existencial en Isaías (8:22; 50:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99682, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que identifica al cabeza ancestral de un clan entre los exiliados que volvieron de Babilonia. La familia aparece en ambas listas censales (Esd 2:19; Neh 7:22), con miembros involucrados en la crisis de los matrimonios mixtos (Esd 10:33). Un personaje llamado חַשֻּׁם está en la plataforma durante la lectura de la Torá por Esdras (Neh 8:4) y sella el pacto (Neh 10:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99684, 'spa', 'Metal resplandeciente', 'Sustancia brillante, posiblemente ámbar o electro, que aparece en visiones divinas. Ezequiel 1:4 describe «la apariencia de un metal resplandeciente» dentro de la nube tormentosa de la venida de Dios. Ezequiel 1:27 lo emplea dos veces para el fulgor que rodea la figura entronizada. Ezequiel 8:2 lo usa para la apariencia ígnea de la figura divina. El contexto visionario constante subraya su carácter sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99687, 'spa', 'Pectoral, pectoral del juicio — el ornamento sagrado en forma de bolsa que lleva', 'Pectoral, pectoral del juicio — el ornamento sagrado en forma de bolsa que llevaba el sumo sacerdote sobre el pecho, engastado con cuatro filas de tres piedras preciosas que representaban las doce tribus de Israel y que contenía el Urim y Tumim para la consulta oracular. Llamado חֹשֶׁן הַמִּשְׁפָּט (''pectoral del juicio'') en Éx 28:15, 30. Estaba sujeto al efod mediante cadenas de oro en los hombros y un cordón azul en la cintura (Éx 28:22-28; 39:8-21). Las 25 ocurrencias se concentran en Éxodo y Levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99692, 'spa', 'Desnudar, exponer', 'Desnudar o dejar al descubierto, removiendo las cubiertas de una persona o cosa. Sentido de gran carga profética: Dios descubre su santo brazo con poder (Is 52:10), mientras Babilonia es avergonzada al levantársele las faldas (Is 47:2; Jer 13:26). El participio pasivo en Ezequiel 4:7 describe el brazo descubierto del profeta como un acto simbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99693, 'spa', 'Descortezar, pelar', 'Descortezar o pelar la capa exterior de un árbol, un sentido agrícola concreto. Joel 1:7 lo emplea dos veces para la devastadora plaga de langostas que peló las higueras de Israel hasta dejarlas desnudas. Este uso se distingue claramente del despojo centrado en personas del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99699, 'spa', 'Sacar agua, extraer', 'Sacar o extraer agua de una cisterna o pozo, extendiendo la idea raíz de ''extraer'' al ámbito líquido. Aparece en Isaías 30:14 (sacar fuego de un hogar o agua de una cisterna) y Hageo 2:16 (ir a sacar de un lagar). Se trata de un uso reconocido como distinto y no de una extensión metafórica del sentido de desnudar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99704, 'spa', 'Apegarse, amar, desear', 'Estar emocionalmente apegado a alguien, amar, poner el deseo en algo. El verbo חָשַׁק transmite un afecto profundo y vinculante; el cognado arameo significa literalmente ''atar o sujetar''. Abarca el deseo romántico humano (Gn 34:8; Dt 21:11), el amor soberano de Dios por Israel (Dt 7:7; 10:15) y la devoción del creyente que desencadena la protección divina (Sal 91:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99711, 'spa', 'Ceñir con molduras', 'Proveer de molduras o filetes, específicamente en la construcción del tabernáculo. Éxodo 27:17 prescribe que las columnas del atrio sean «anilladas de plata». Éxodo 38:17 describe la obra ejecutada: las columnas «fueron ceñidas con plata». Éxodo 38:28 señala la labor de Bezalel: «las ciñó con molduras», conectando las columnas con filetes de plata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99712, 'spa', 'Deseo o deleite', 'Deseo o deleite, ya sea el anhelo abstracto o la cosa concreta deseada. En 1 Reyes 9:1, 19 y 2 Crónicas 8:6 se refiere a los proyectos constructivos anhelados por Salomón (''el deseo de Salomón''). En Isaías 21:4 describe el placer o deleite personal —''el crepúsculo de mi deleite''— transformado en horror. Abarca tanto la aspiración como el objeto que la satisface.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99713, 'spa', 'Molduras o anillos metálicos', 'Molduras, anillos o bandas metálicas que ciñen y rodean las columnas del tabernáculo, asegurando el sistema de cortinas. Aparecen solo en plural con sufijos posesivos, exclusivamente en los textos sacerdotales del tabernáculo (Éx 27:10, 11; 36:38; 38:10, 11, 12, 17, 19). Las bandas de las columnas del atrio estaban revestidas de plata, mientras que las de la entrada de la tienda eran de oro (Éx 36:38).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99718, 'spa', 'Gentilicio de Husá', 'Adjetivo gentilicio (''el husatita'') que denota procedencia de Husá, una ciudad de Judá. Las cinco ocurrencias sirven como epíteto de guerreros de élite de David: Sibecai, quien mató al gigante filisteo Saf (2 S 21:18; 1 Cr 20:4) y comandaba una división militar (1 Cr 27:11), y Mebunai/Ilai entre los Treinta (2 S 23:27; 1 Cr 11:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99720, 'spa', 'Quebrantado o consternado', 'Destrozado, quebrantado o consternado por la derrota o el terror. 1 Samuel 2:4 celebra que «el arco de los poderosos es quebrado», mientras los débiles hallan fuerza. Isaías 7:8 profetiza que «dentro de sesenta y cinco años Efraín será destrozado». Jeremías 46:5 describe a los guerreros egipcios «consternados» y huyendo aterrados ante Babilonia. El doble sentido de quiebre físico y psicológico subraya la destrucción total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99721, 'spa', 'Het (nombre étnico)', 'Nombre propio Het (חֵת), antepasado epónimo de los hititas, presentado como hijo de Canaán (Gn 10:15; 1 Cr 1:13). Casi todas las ocurrencias emplean la fórmula ''hijos de Het'' (בְּנֵי חֵת) para designar a la población hitita residente en Hebrón durante el período patriarcal, particularmente en la narrativa de la compra de Macpela (Gn 23:3–20; 25:10; 49:32). La expresión ''hijas de Het'' (בְּנוֹת חֵת) en Gn 27:46 alude a las esposas hititas de Esaú.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99723, 'spa', 'Arrebatar fuego o brasas', 'Tomar o arrebatar fuego o carbones de una fuente. Isaías 30:14 describe tomar fuego de un hogar; Proverbios 6:27 lo usa metafóricamente para tomar fuego en el seno (símil de las consecuencias del adulterio); Proverbios 25:22 lo extiende a amontonar brasas sobre la cabeza de alguien. En el Salmo 52:5, Dios arranca al impío de entre los vivos, ampliando el verbo al juicio divino destructivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99727, 'spa', 'Hitita (gentilicio) — Sustantivo o adjetivo gentilicio que designa a un miembro ', 'Hitita (gentilicio) — Sustantivo o adjetivo gentilicio que designa a un miembro del pueblo hitita, usado para individuos nombrados específicamente (Efrón el hitita en Gn 23:10; Urías el hitita en 2 S 11:3), en listas formulaicas de naciones cananeas (Éx 3:8; Dt 7:1; Jos 3:10), y de mujeres hititas amadas por Salomón (1 R 11:1). El término también tiene fuerza geográfica en Jos 1:4, refiriéndose al territorio hitita más amplio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99742, 'spa', 'Terror, espanto', 'Terror o espanto que los reinos y guerreros poderosos infundían entre los vivientes, ahora extinguido en la muerte. Usado exclusivamente en los oráculos de Ezequiel: Tiro causó terror en los mares (Ez 26:17) y la frase ''infundieron su terror en la tierra de los vivientes'' se repite como estribillo solemne en el poema del descenso al Seol (Ez 32:23-32), aplicado a Asiria, Elam, Mesec-Tubal, Edom y Sidón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99751, 'spa', 'Sellar, fijar un sello — el sentido activo central del Qal', 'Sellar, fijar un sello — el sentido activo central del Qal: sellar, estampar el sello propio sobre un documento u objeto para autenticación, autorización o clausura. Abarca el sellado real con anillo de sellar (1 Re 21:8; Est 8:8, 8:10), Dios sellando las estrellas para que no brillen (Job 9:7) y el mandato profético de sellar el testimonio de Isaías (Is 8:16). Con 12 ocurrencias, es el sentido más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99752, 'spa', 'Sellado (estado) — el participio pasivo del Qal usado como adjetivo', 'Sellado (estado) — el participio pasivo del Qal usado como adjetivo: en estado sellado. Con 10 ocurrencias, describe documentos, fuentes y objetos que llevan la marca de haber sido sellados. Deuteronomio 32:34 guarda los juicios de Dios ''sellados entre mis tesoros''; Cantares 4:12 alaba a la amada como ''fuente sellada''; Nehemías 9:38-10:1 enumera a los que firmaron ''el documento sellado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99760, 'spa', 'Tapar, obstruir — sentido extendido del Hifil', 'Tapar, obstruir — sentido extendido del Hifil: tapar u obstruir, aplicado a una secreción corporal en Levítico 15:3. La metáfora transfiere la clausura de un documento sellado a la clausura de una abertura física. Una sola ocurrencia, pero el tallo causativo Hifil y el contexto de fluidos corporales lo distinguen claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99763, 'spa', 'Ser sellado (pasivo) — el Nifal pasivo', 'Ser sellado (pasivo) — el Nifal pasivo: ser sellado, enfocando la acción de sellar desde la perspectiva del documento. Ambas ocurrencias están en Ester (3:12; 8:8), describiendo edictos reales sellados con el anillo del rey. El Nifal distingue este sentido del participio del sentido 2: aquí el sellado es un evento narrado (''fue sellado''), no un estado resultante (''está sellado'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99764, 'spa', 'Cerrar herméticamente (Piel) — el Piel intensivo', 'Cerrar herméticamente (Piel) — el Piel intensivo: cerrar o sellar herméticamente con énfasis en la completitud. Job 24:16 describe a ladrones que ''se sellan'' de día, ocultándose en casas que marcaron para robar de noche. La intensificación del Piel sugiere un sellado minucioso y deliberado, no un simple estampado sino un atrincheramiento cuidadoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99769, 'spa', 'El que sella, sellador — participio activo del Qal usado como sustantivo agente', 'El que sella, sellador — participio activo del Qal usado como sustantivo agente: ''el que sella, el sellador''. En Ezequiel 28:12, el rey de Tiro es llamado חוֹתֵם תָּכְנִית — traducido variadamente como ''sello de perfección'' o ''modelo de proporción''. El uso como sustantivo agente participial es una derivación estándar del hebreo, pero el contexto único en Ezequiel le confiere una carga simbólica excepcional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99775, 'spa', 'Suegro (padre de la esposa) — la forma masculina constructa ḥoten, que aparece 2', 'Suegro (padre de la esposa) — la forma masculina constructa ḥoten, que aparece 21 veces, siempre con el significado de ''padre de la esposa'' o ''suegro''. Abrumadoramente ligado al suegro de Moisés a lo largo de Éxodo 3-18, Números 10:29 y Jueces 1:16 y 4:11. También se usa del suegro de un levita anónimo en Jueces 19:4, 7, 9. La raíz árabe khātin (''circuncidador'') refleja la antigua práctica del Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99778, 'spa', 'Suegra (madre de la esposa) — una única forma femenina ḥotanto en Deuteronomio 2', 'Suegra (madre de la esposa) — una única forma femenina ḥotanto en Deuteronomio 27:23, que significa ''su suegra (madre de la esposa)''. Esta ocurrencia solitaria aparece en las maldiciones del pacto de Siquem: ''Maldito el que se acueste con su suegra''. Su ubicación entre las relaciones sexuales prohibidas subraya la gravedad del tabú de parentesco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99780, 'spa', 'Hacerse yerno', 'Hacerse yerno de alguien, entrando en una familia específica al casarse con la hija. Las cinco apariciones se concentran en 1 Samuel 18:21-27, donde David es invitado y luego se esfuerza por convertirse en yerno de Saúl. La fuerza reflexiva del Hitpael es expresiva: David se hace activamente yerno, asumiendo el papel con determinación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99782, 'spa', 'Emparentar, aliarse por matrimonio', 'Formar una alianza matrimonial o emparentar entre familias, clanes o naciones: un acto sociopolítico más que un compromiso personal. Se emplea en contextos de matrimonios prohibidos con extranjeros (Dt 7:3; Jos 23:12; Esd 9:14) y de alianzas políticas selladas por medio de enlaces matrimoniales. El énfasis recae en el pacto relacional entre grupos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99789, 'spa', 'Novio', 'Novio: un novio, el hombre que se casa, especialmente en el contexto de celebraciones nupciales e imágenes de bodas. El sol sale como un חָתָן de su cámara (Sal 19:5); los redimidos se visten de salvación como un חָתָן que se pone una guirnalda sacerdotal (Isa 61:10). El enigmático ''novio de sangre'' (חֲתַן דָּמִים) en Éxodo 4:25-26 conecta el término con los ritos de circuncisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99790, 'spa', 'Yerno', 'Yerno: el esposo de una hija, un yerno, designando al hombre en relación con el padre de su esposa. Los חֲתָנָיו de Lot son los que se habían casado con sus hijas (Gén 19:14); los filisteos identifican a Sansón como el חָתָן del timnateo (Jue 15:6); y el suegro de un levita hospeda a su חָתָן con generosa hospitalidad (Jue 19:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99801, 'spa', 'Cavar, perforar', 'Cavar, perforar o abrir paso a través de un muro, barrera o el suelo. Sentido principal en siete apariciones. Ezequiel perfora la muralla de Jerusalén como acto simbólico (Ez 8:8; 12:5, 7, 12), Job describe ladrones que cavan casas en la oscuridad (Job 24:16), y Amós 9:2 imagina cavar hasta el Seol para escapar del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99804, 'spa', 'Remar', 'Remar un bote — extensión metafórica vívida donde los remos «cavan en» el agua. Atestiguado únicamente en Jonás 1:13: וַיַּחְתְּרוּ הָאֲנָשִׁים («y los hombres remaron con fuerza»), cuando los marineros intentaban desesperadamente llevar el barco a tierra durante la tormenta. Todas las tradiciones reconocen esta acción náutica como distinta de la excavación literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99808, 'spa', 'Estar desalentado o aterrorizado — El sentido emocional dominante', 'Estar desalentado o aterrorizado — El sentido emocional dominante: llenarse de pavor, terror o desaliento que paraliza la acción. Es el verbo de la exhortación en el campo de batalla: «no temas ni desmayes» (Jos 1:9; Dt 31:8). El español «desmayar» (perder el ánimo) revela el colapso interior de la voluntad que esta palabra describe. Aparece característicamente en pares con יָרֵא (''temer'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99810, 'spa', 'Ser quebrantado o destrozado — El sentido físico concreto de ser roto, destrozad', 'Ser quebrantado o destrozado — El sentido físico concreto de ser roto, destrozado o hecho pedazos. En Isaías 8:9, se provoca a las naciones tres veces con el imperativo «¡sed quebrantados!» — una declaración profética de su destrucción. En Isaías 30:31, Asiria «será quebrantada» por la voz del SEÑOR. Este sentido proporciona la metáfora raíz del campo semántico completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99825, 'spa', 'Aterrorizar o causar espanto — La dimensión causativa (Hifil/Piel)', 'Aterrorizar o causar espanto — La dimensión causativa (Hifil/Piel): aterrorizar, espantar o quebrantar activamente a alguien. En Job 7:14, el sufriente acusa directamente a Dios: «Me espantas con sueños». Jeremías 1:17 contiene un notable juego de palabras: Dios le dice a Jeremías que no se quebrante (תֵּחַת) ante ellos, no sea que Dios lo quebrante (אֲחִתְּךָ) ante ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99844, 'spa', 'Quebrantar (liberación divina) — Una única aparición en Isaías 9', 'Quebrantar (liberación divina) — Una única aparición en Isaías 9:4 [Heb. 9:3] donde el verbo aparece en el contexto de la liberación divina: «la vara de su opresor, tú la quebrantaste». El español usa «quebrantaste», señalando la rotura victoriosa de un instrumento de opresión, fusionando el quebrantamiento físico con el espanto que produce en el opresor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99853, 'spa', 'Degollar, matar', 'Degollar o matar un animal para alimento, banquete o sacrificio. José ordena que se degüelle una res para el festín (Gn 43:16), la Sabiduría degüella sus carnes (Pr 9:2), el ladrón degüella un buey robado (Éx 22:1) y la maldición del pacto amenaza con ganado degollado ante los ojos impotentes del dueño (Dt 28:31). También 1 Samuel 25:11, donde las provisiones de Nabal incluyen carne que él ha matado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99862, 'spa', 'Matanza, degüello', 'Acto de degollar animales para alimento, banquete o sacrificio, que se extiende metafóricamente a la masacre en contextos bélicos. En lo doméstico: la preparación del banquete de José (Gn 43:16) y la invitación de la Sabiduría (Pr 9:2). En lo profético y militar: el día de la matanza de Yahvé (Is 34:2, 6), enemigos llevados como corderos al degüello (Jer 48:15; 51:40) y la espada de matanza (Ez 21:15, 33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99870, 'spa', 'verdugo, guardia de corps (degollador real)', 'verdugo, guardia de corps (degollador real)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99873, 'spa', 'cocinero, el que degüella y prepara la comida', 'cocinero, el que degüella y prepara la comida');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99876, 'spa', 'Carne para matanza', 'Carne sacrificada o animales destinados a la matanza. 1 Samuel 25:11 habla de «mi carne que he degollado para mis esquiladores», las provisiones del banquete de Nabal. Salmo 44:22 lamenta que «somos contados como ovejas para el matadero», enfrentando persecución. Jeremías 12:3 pide que los impíos sean «apartados como ovejas para el degüello» en juicio divino. Los usos literales y metafóricos comparten la imagen de animales señalados para la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99879, 'spa', 'Mojar en líquido', 'Mojar en líquido: meter un objeto en un líquido, el sentido activo central del Qal que abarca 13 de las 16 apariciones del verbo. La acción es siempre transitiva: alguien moja algo (dedo, hisopo, pan, vara) en una sustancia (sangre, agua, vinagre, miel). Predominan los contextos rituales: sacerdotes levíticos mojando dedos en sangre para ritos de purificación (Lev 4:6, 17; 9:9; 14:6, 51) y el hisopo pascual mojado en la sangre del cordero (Éx 12:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99884, 'spa', 'Sumergirse completamente (inmersión total)', 'Sumergirse completamente (inmersión total): hundir o sumergir completamente, sugiriendo una inmersión total en vez de un mojado parcial. Naamán se sumerge siete veces en el Jordán para su sanación (2 Re 5:14), y Job se queja amargamente de que Dios lo ''hundiría en un hoyo'' (Job 9:31). Este sentido connota una acción más enérgica y de cuerpo entero que anticiparía el vocabulario arameo y griego del bautismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99887, 'spa', 'Ser mojado o sumergido (Nifal pasivo)', 'Ser mojado o sumergido (Nifal pasivo): ser mojado o quedar sumergido, forma Nifal (pasiva) que aparece únicamente en Josué 3:15, donde los sacerdotes que llevaban el arca entraron al Jordán en época de crecida y sus pies ''se mojaron'' en el borde del agua. El contexto narrativo es electrizante: en el instante del contacto, las aguas se detienen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99890, 'spa', 'Hundirse en agua o cieno', 'Sentido básico del Qal: hundirse en una sustancia blanda — agua, lodo o tierra húmeda — ya sea literalmente (Jeremías en la cisterna, Jer 38:6) o como metáfora de angustia abrumadora (Sal 69:2–3, 14). El sujeto es arrastrado indefenso hacia abajo, con la preposición bet marcando el medio que lo engulle.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99891, 'spa', 'Ser hundido, asentarse', 'Sentido del Hofal (causativo-pasivo): ser hecho hundir o quedar firmemente asentado. En Job 38:6 Dios pregunta quién hundió los cimientos de la tierra; en Proverbios 8:25 los montes fueron asentados ante los ojos de la Sabiduría. Jeremías 38:22 advierte que los pies del rey han sido hundidos en el lodo: otros han causado su caída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99896, 'spa', 'Ser ahogado, sumergido', 'El Pual (pasivo intensivo) en Éxodo 15:4, donde los oficiales escogidos del faraón «fueron hundidos» en el mar Rojo. La raíz intensiva subraya la totalidad: no simplemente hundirse, sino quedar completamente sumergido y destruido, una inmersión enfática e irrecuperable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99897, 'spa', 'Clavarse, incrustarse', 'Uso especializado del Qal en 1 Samuel 17:49, donde la piedra de la honda se hunde en la frente de Goliat, incrustándose en hueso sólido en vez de en líquido o lodo. La semántica básica de «hundirse en» se extiende naturalmente a la penetración de una superficie dura, señalando que el hebreo טָבַע trata la inmersión en sólido y en líquido como un mismo campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99901, 'spa', 'Argolla o anilla de sujeción — Anillo o argolla funcional de metal fijada a los ', 'Argolla o anilla de sujeción — Anillo o argolla funcional de metal fijada a los enseres del tabernáculo (arca, altar, mesa, efod) a través de la cual se pasaban varas o cuerdas para su transporte o fijación. Este es el uso dominante (40 ocurrencias), concentrado en Éxodo 25–39. El español «argollas» capta el carácter utilitario de este sentido (Éx 25:12–15; 26:24; 28:23–28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99903, 'spa', 'Anillo de sello — Un anillo que se lleva en el dedo, especialmente uno que porta', 'Anillo de sello — Un anillo que se lleva en el dedo, especialmente uno que porta un sello usado para autenticación y como marca de autoridad delegada. Faraón se quita su anillo de sello y lo pone en la mano de José (Gn 41:42), y el anillo de Asuero sella decretos reales (Est 3:10–12; 8:2, 8, 10). También aparece entre joyas ornamentales (Is 3:21; Nm 31:50; Éx 35:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99918, 'spa', 'Ritualmente limpio — Pureza ritual o ceremonial según el sistema levítico', 'Ritualmente limpio — Pureza ritual o ceremonial según el sistema levítico. Los animales limpios se distinguen de los impuros para el sacrificio y la dieta (Gn 7:2; 8:20; Lv 20:25; Dt 14:11); las personas quedan limpias tras los ritos de purificación (Lv 13:13, 17; Nm 9:13); lugares y utensilios se designan limpios para uso sagrado (Lv 4:12; 10:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99919, 'spa', 'Puro en sustancia — Pureza de sustancia material', 'Puro en sustancia — Pureza de sustancia material: sin mezcla, refinado o de la más alta calidad. Este sentido domina la narración de la construcción del tabernáculo: oro puro (zahav tahor) recubriendo el arca, el propiciatorio, la mesa, el candelabro (Éx 25:11, 17, 24, 31); incienso puro sobre los panes de la proposición (Lv 24:7); aceite puro para las lámparas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99928, 'spa', 'Moral o espiritualmente puro — Pureza moral o espiritual del corazón, el carácte', 'Moral o espiritualmente puro — Pureza moral o espiritual del corazón, el carácter o la conducta. El Salmo 19:9 declara que «el temor del SEÑOR es limpio (tehorah), que permanece para siempre» — no ritualmente limpio como un animal ni materialmente puro como el oro, sino ética y espiritualmente inmaculado. Este sentido eleva el significado al ámbito de lo sagrado y lo moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99929, 'spa', 'Pureza (uso nominal) — Un uso nominal abstracto en estado constructo que signifi', 'Pureza (uso nominal) — Un uso nominal abstracto en estado constructo que significa «pureza de» o «limpieza de», funcionando como sustantivo y no como adjetivo. Ambas ocurrencias aparecen en Proverbios 22:11, donde «pureza de corazón» (tehor lev) describe la limpieza interior como cualidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99936, 'spa', 'Qal', 'Qal: estar limpio, ser puro — Qal estativo: estar o llegar a estar ritual, moral o físicamente limpio. El sujeto experimenta o alcanza un estado de pureza: un leproso tras la inmersión (Lv 14:8-9), un objeto tras el lavado al atardecer (Lv 11:32), o una mujer tras su período de purificación (Lv 12:7-8). La mayoría de las ocurrencias se concentran en la legislación levítica de pureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99937, 'spa', 'Hitpael', 'Hitpael: purificarse — Hitpael reflexivo: purificarse a sí mismo, someterse a la autopurificación. El sujeto toma una acción deliberada para alcanzar la pureza ritual, a menudo en preparación para el culto o un encuentro sagrado. Jacob ordena a su familia purificarse (Gn 35:2); los exiliados retornados y los levitas se purifican para la Pascua (Esd 6:20; Neh 12:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99938, 'spa', 'Piel declarativo', 'Piel declarativo: declarar puro — Piel declarativo: pronunciar o declarar ritualmente limpio. Un término técnico sacerdotal donde el sacerdote declara formalmente que una persona u objeto está libre de impureza, concentrado casi enteramente en la legislación sobre enfermedades de la piel de Levítico 13–14. El sacerdote examina y luego «declara limpio» (Lv 13:6, 13, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99939, 'spa', 'Piel factitivo', 'Piel factitivo: limpiar, purificar — Piel factitivo: limpiar, purificar o hacer limpio activamente. El agente realiza una acción purificadora sobre una persona, lugar u objeto. Dios es frecuentemente el sujeto en textos proféticos: «Os limpiaré de todas vuestras impurezas» (Ez 36:25; 37:23). Los sacerdotes limpian el altar (Lv 16:19) y los levitas son purificados para el servicio (Nm 8:6-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99982, 'spa', 'Pual', 'Pual: ser purificado — Una única aparición en Pual (o Piel pasivo anómalo) en Ezequiel 22:24, que describe una tierra «no purificada» — es decir, no limpiada ni regada en el día de la indignación. Se interpreta mejor como contraparte pasiva del Piel factitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (99993, 'spa', 'Purificación, limpieza', 'El proceso o estado de purificación ritual y limpieza ceremonial, empleado en las leyes levíticas de pureza. Abarca la purificación posparto (Lv 12:4–6), la limpieza de enfermedades cutáneas (Lv 13:7, 35; 14:2, 23, 32), la restauración tras flujo corporal (Lv 15:13), la reconsagración del nazareo (Nm 6:9), la purificación sacerdotal por contaminación con cadáveres (Ez 44:26) y el mantenimiento general de la pureza del templo (Neh 12:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100003, 'spa', 'Ser bueno, ser agradable — sentido estativo del Qal', 'Ser bueno, ser agradable — sentido estativo del Qal: ser bueno, placentero o aceptable, frecuentemente en la expresión evaluativa ''bueno a los ojos de alguien''. Se usa para describir cosas, situaciones o condiciones favorables: Balaam ve que es bueno a los ojos de Dios bendecir a Israel (Nm 24:1), y las tiendas de Jacob son llamadas טוֹב (Nm 24:5). Las traducciones convergen en la bondad básica: bueno, bien, bon, gut.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100005, 'spa', 'Hacer bien, actuar correctamente — sentido causativo del Hifil', 'Hacer bien, actuar correctamente — sentido causativo del Hifil: hacer bien, actuar correctamente o tratar generosamente a alguien. El agente produce bondad de forma activa. Dios promete hacer bien a Israel y regocijarse sobre ellos (Jer 32:41); el salmista declara ''Tú eres bueno y haces bien'' (Sal 119:68). El enfoque pasa del estado a la acción benevolente deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100015, 'spa', 'bueno (calidad o moral)', 'El sentido adjetival nuclear: moralmente recto, prácticamente adecuado o de cualidad intrínsecamente deseable. Este grupo masivo (305 ocurrencias) ancla el uso de la palabra desde Génesis 1 («vio Dios que era bueno») hasta las exhortaciones deuteronómicas a hacer «lo bueno y lo recto» (Dt 6:18; 12:28). La convergencia de inglés good, español bueno, francés bon, alemán gut, árabe khayr y coreano 좋은 confirma su extensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100016, 'spa', 'mejor (comparativo)', 'El grado comparativo y superlativo: «mejor que», «lo mejor de». Con 64 ocurrencias, constituye un subsentido robusto, marcado formalmente por comparaciones con מִן y contextualmente por un juicio evaluativo. El árabe khayrun (comparativo) y el español mejor despliegan morfología comparativa dedicada en vez del adjetivo base, confirmando que se trata de un uso lexicalizado. Especialmente frecuente en Eclesiastés y Proverbios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100018, 'spa', 'bondad (sustantivo)', 'Uso nominalizado o sustantivo: «lo bueno», «la bondad», «el bienestar», «la prosperidad» como entidad abstracta. Con 28 apariciones, este sentido trata a טוֹב no como descriptor sino como la cosa misma: lo bueno que uno hace o experimenta. El árabe al-khayr (con artículo definido) y el coreano 선함/선 (bondad como sustantivo) marcan claramente la nominalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100036, 'spa', 'hermoso, bello (apariencia)', 'Belleza estética o atractivo físico, especialmente de personas o tierras. Solo 8 ocurrencias, pero marcadas de forma diferenciada interlingüísticamente: el árabe ḥasan/jamīlat («hermosa»), el coreano 아름다운 y el español hermosa seleccionan vocabulario específico de belleza en vez de un genérico «bueno». La frase טוֹבַת מַרְאֶה («buena de aspecto») en Gn 24:16; 26:7 es prácticamente una fórmula técnica para la belleza femenina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100069, 'spa', 'alegre, contento (de corazón)', 'Estado emocional de alegría o regocijo, limitado al modismo לֵב טוֹב («el corazón estaba bueno»). Con solo 5 ocurrencias, es un sentido compacto pero inconfundible: el corazón se pone «bueno» por el festín, el vino o la ocasión gozosa (Jue 16:25; 2 S 13:28; Est 1:10). El árabe ṭāba («volverse grato/alegre»), el hindi prasanna y el español se alegraron giran todos hacia el vocabulario emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100096, 'spa', 'El bien, lo bueno — La inmensa mayoría de las ocurrencias (unas 85 de 90) usan ט', 'El bien, lo bueno — La inmensa mayoría de las ocurrencias (unas 85 de 90) usan טוֹב como sustantivo general que significa «el bien» o «lo bueno», abarcando dimensiones morales, éticas y prácticas. Aparece en pasajes fundacionales como Gn 2:9 («el árbol del conocimiento del bien y del mal») y Gn 3:5, 22, donde el concepto define el límite del conocimiento humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100107, 'spa', 'Prosperidad, bienestar — Tres pasajes estrechan el campo semántico a la prosperi', 'Prosperidad, bienestar — Tres pasajes estrechan el campo semántico a la prosperidad concreta, el bienestar material o las condiciones favorables de vida. En 1 R 1:42, Ahimaaz dice que trae «bien» (es decir, buenas noticias de prosperidad); en 1 R 10:7, la reina de Sabá describe la sabiduría y el טוֹב (esplendor material) de Salomón; el Sal 25:13 promete que el justo «morará en el bien» (disfrutará prosperidad).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100108, 'spa', 'Bondad, buena cualidad — Dos ocurrencias (Pr 2', 'Bondad, buena cualidad — Dos ocurrencias (Pr 2:9; Os 10:1) usan טוֹב para describir la cualidad intrínseca o grado de excelencia de algo — su buen carácter o naturaleza. En Pr 2:9, entender la justicia incluye discernir toda «buena senda» o cualidad; en Os 10:1, el fruto de Israel aumenta «conforme a la bondad» de su tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100116, 'spa', 'Beneficio, bienestar — Bien dirigido hacia un beneficiario específico como biene', 'Beneficio, bienestar — Bien dirigido hacia un beneficiario específico como bienestar, beneficio o bien particular. La preposición lamed («para bien») y los sufijos posesivos («su bien») señalan este sentido relacional y direccional. Génesis 50:20 es el ejemplo paradigmático: «Dios lo encaminó para bien». Las promesas del pacto en Deuteronomio (28:11; 30:9) concretan este bien como prosperidad otorgada por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100117, 'spa', 'Bondad, bien moral — La cualidad abstracta de la bondad o el bien moral', 'Bondad, bien moral — La cualidad abstracta de la bondad o el bien moral: lo que es recto, beneficioso y digno de alabanza. Apareciendo frecuentemente con artículo («el bien») o en cadenas constructas, este sentido domina la distribución (41 ocurrencias). Pasajes clave incluyen Jueces 8:35, donde Israel no corresponde a la bondad de Gedeón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100123, 'spa', 'Cosas buenas, buenas obras — Instancias concretas y contables del bien', 'Cosas buenas, buenas obras — Instancias concretas y contables del bien: cosas buenas, bendiciones o buenas obras, marcadas por la morfología plural. Jeremías 12:6 advierte que incluso los familiares que «hablan cosas buenas» pueden ser traicioneros, mientras que 2 Reyes 25:28 y Jeremías 52:32 describen el trato favorable dado al rey Joaquín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100127, 'spa', 'Generosidad divina — Generosidad o bondad divina, dirigida directamente a Dios c', 'Generosidad divina — Generosidad o bondad divina, dirigida directamente a Dios con sufijos posesivos de segunda persona. En el Salmo 65:11 el año es coronado con «Tu bondad» y en el Salmo 68:10 Dios provee de «Tu bondad» al pobre. Este sentido se distingue por un registro intensificado y doxológico, más que meramente ético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (100135, 'spa', 'Región geográfica', 'Tob, región geográfica al este del Jordán, en las cercanías de Galaad y el sur de Basán. Jefté se refugió allí tras ser expulsado por sus hermanos (Jue 11:3, 5), y sus guerreros sirvieron como aliados de los amonitas contra las fuerzas de David (2 Sam 10:6, 8). El nombre, que significa «bueno», se transliteran uniformemente en todas las tradiciones lingüísticas principales.');